import React from "react";
import { COLORS, FONT_DISPLAY } from "../constants/theme";

export default function About() {
  return (
    <section style={{ padding: "80px 22px", maxWidth: 720, margin: "0 auto" }}>
      <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 34, marginBottom: 20, color: COLORS.text }}>
        Our story
      </h1>
      <p style={{ fontSize: 15, lineHeight: 1.7, color: COLORS.textMuted, marginBottom: 16 }}>
        Every piece we make starts with reclaimed gold — old jewelry, given a second life
        instead of ending up forgotten in a drawer. We melt it down, re-cast it, and shape
        it into something new by hand.
      </p>
      <p style={{ fontSize: 15, lineHeight: 1.7, color: COLORS.textMuted }}>
        We're a small, local studio. No mass production, no middlemen — just careful work,
        made close to home.
      </p>
    </section>
  );
}
